mapper.select:
SELECT w.region_id AS regionId, li.sku_code AS skuCode, SUM(CASE WHEN li.quality = 'GOOD' THEN li.quantity - li.reserved_quantity ELSE 0 END) AS totalAvailable, SUM(CASE WHEN li.quality = 'GOOD' THEN li.reserved_quantity ELSE 0 END) AS totalReserved, 0 AS totalInTransit, SUM(CASE WHEN li.quality = 'DEFECTIVE' THEN li.quantity ELSE 0 END) AS totalDamaged FROM wms_location_inventory li INNER JOIN wms_warehouse w ON w.id = li.warehouse_id AND w.deleted = 0 AND w.status = 1 AND w.warehouse_type = 'OWN' WHERE li.deleted = 0
AND w.region_id IN #{id}
AND li.sku_code LIKE CONCAT('%', #{keyword}, '%') GROUP BY w.region_id, li.sku_code

SELECT w.region_id AS regionId, COUNT(DISTINCT li.warehouse_id) AS warehouseCount, SUM(CASE WHEN li.quality = 'GOOD' THEN li.quantity - li.reserved_quantity ELSE 0 END) AS totalAvailable, SUM(CASE WHEN li.quality = 'GOOD' THEN li.reserved_quantity ELSE 0 END) AS totalReserved, 0 AS totalInTransit, SUM(CASE WHEN li.quality = 'DEFECTIVE' THEN li.quantity ELSE 0 END) AS totalDamaged FROM wms_location_inventory li INNER JOIN wms_warehouse w ON w.id = li.warehouse_id AND w.deleted = 0 AND w.status = 1 AND w.warehouse_type = 'OWN' WHERE li.deleted = 0
AND w.region_id IN #{id}
GROUP BY w.region_id
